import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect, test, type Page } from '@playwright/test';
import { findBoCli } from '../collab/ports.mjs';

// Hostile files opened in the web app (BlueOffice-PARITY-PROMPT §9.4; the engine-level suite
// is crates/bo-engine/tests/hostile_files.rs). The samples are generated by
// `bo-cli sample-hostile` (nothing downloaded) with every external target pointing at
// http://127.0.0.1:9 / file:// / UNC. Every request the page makes is routed: anything that
// leaves the app's origin fails the test (and is aborted). Each file either opens or shows the
// "cannot open" message, the page never throws, and the editor stays usable.

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const cli = findBoCli(root);
test.skip(!cli, 'needs a built bo-cli (cargo build -p bo-cli)');

let dir = '';
test.beforeAll(() => {
  dir = mkdtempSync(join(tmpdir(), 'bo-hostile-e2e-'));
  execFileSync(cli!, ['sample-hostile', dir], { stdio: 'ignore' });
});
test.afterAll(() => {
  if (dir) rmSync(dir, { recursive: true, force: true });
});

/** Route every request; collect the ones that leave the origin of the app. */
async function watchNetwork(page: Page, baseURL: string) {
  const origin = new URL(baseURL).origin;
  const outside: string[] = [];
  await page.route('**/*', (route) => {
    const url = route.request().url();
    const u = new URL(url);
    if (u.origin === origin || u.protocol === 'data:' || u.protocol === 'blob:') {
      return route.continue();
    }
    outside.push(url);
    return route.abort();
  });
  page.on('request', (r) => {
    const u = new URL(r.url());
    if (u.origin !== origin && u.protocol !== 'data:' && u.protocol !== 'blob:') {
      if (!outside.includes(r.url())) outside.push(r.url());
    }
  });
  return outside;
}

async function open(page: Page, file: string) {
  const chooser = page.waitForEvent('filechooser');
  await page.locator('[data-command="file.open"]').first().click();
  await (await chooser).setFiles(join(dir, file));
}

/** BlueDoc opens files from File › Open. */
async function openDoc(page: Page, file: string) {
  await page.getByTestId('file-tab').click();
  await page
    .getByRole('navigation', { name: 'Tệp' })
    .getByRole('button', { name: 'Mở', exact: true })
    .click();
  const chooser = page.waitForEvent('filechooser');
  await page.locator('[data-testid="backstage"] [data-command="file.open"]').click();
  await (await chooser).setFiles(join(dir, file));
}

const DOC_FILES: [string, 'open' | 'reject'][] = [
  ['external-relationships.docx', 'open'],
  ['include-fields.docx', 'open'],
  ['remote-template.docx', 'open'],
  ['svg-script.docx', 'open'],
  ['web-script.html', 'open'],
  ['web-script.mht', 'open'],
  ['pdf-actions.pdf', 'open'],
  ['zip-bomb-ratio.docx', 'reject'],
  ['xml-deep-nesting.docx', 'reject'],
];

test('BlueDoc: hostile files open inert or are refused; nothing leaves the origin', async ({
  page,
  baseURL,
}) => {
  test.setTimeout(180_000);
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  const outside = await watchNetwork(page, baseURL!);
  await page.goto('/doc');
  await page.getByTestId('new-document').click();
  await expect(page.getByTestId('caret')).toBeVisible();
  for (const [file, expected] of DOC_FILES) {
    await test.step(file, async () => {
      await openDoc(page, file);
      if (expected === 'open') {
        await expect(page.getByTestId('doc-name')).toContainText(file.replace(/\.\w+$/, ''));
        await expect(page.locator('.bo-page[data-page="1"]')).toHaveAttribute(
          'data-rendered',
          'true',
        );
        // No script text reached the document.
        await expect(page.getByText('BO-HOSTILE-SCRIPT')).toHaveCount(0);
      } else {
        await expect(page.getByText(/Không mở được tệp/).first()).toBeVisible();
      }
    });
  }
  // Still usable: type into the open document.
  await page.locator('.bo-page[data-page="1"]').click();
  await page.keyboard.insertText('ok');
  expect(outside, outside.join('\n')).toEqual([]);
  expect(errors, errors.join('\n')).toEqual([]);
});

test('BlueSheet and BlueSlide: DDE / external links / macros / OLE stay inert', async ({
  page,
  baseURL,
}) => {
  test.setTimeout(180_000);
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  const outside = await watchNetwork(page, baseURL!);
  await page.goto('/sheet');
  await expect(page.getByTestId('sheet-canvas')).toHaveAttribute('data-rendered', /\d+/);
  for (const file of ['dde-external-links.xlsx', 'hyperlinks-unsafe.xlsx', 'macro-vba.xlsm']) {
    await test.step(file, async () => {
      await open(page, file);
      await expect(page.getByTestId('doc-name')).toContainText(file.replace(/\.\w+$/, ''));
      await expect(page.getByTestId('sheet-canvas')).toHaveAttribute('data-rendered', /\d+/);
    });
  }
  // The macro bar says the macros are kept and never run.
  await expect(page.getByTestId('macro-warning')).toBeVisible();

  await page.goto('/slide');
  for (const file of ['external-links.pptx', 'ole-embedded-exe.pptx', 'svg-script.pptx']) {
    await test.step(file, async () => {
      await open(page, file);
      await expect(page.getByTestId('slide-status')).toHaveText(/^Slide 1 \/ \d+$/);
      await expect(page.getByTestId('slide-overlay')).toBeVisible();
    });
  }
  expect(outside, outside.join('\n')).toEqual([]);
  expect(errors, errors.join('\n')).toEqual([]);
});
